"A monthly newsletter goes to every registered buyer. Announce a new brand, a new supply or an offer; or sponsor a tile on the home page. Always marked, never changes the order of offers.": "ወርሃዊ ጋዜጣ ለእያንዳንዱ የተመዘገበ ገዢ ይላካል። አዲስ ብራንድ፣ አዲስ አቅርቦት ወይም ቅናሽ ያስተዋውቁ፤ ወይም በመነሻ ገጹ ላይ አንድ ሳጥን ስፖንሰር ያድርጉ። ሁልጊዜ ምልክት ይደረግበታል፣ የቅናሾችን ቅደም ተከተል ፈጽሞ አይቀይርም።",
