"A newsletter item, a banner in the slideshow, a featured-supplier card or a price-pulse tile. Press the button to see the placements, the example prices and the form.": "የጋዜጣ ጽሑፍ፣ በተንሸራታች ምስሎች ውስጥ ባነር፣ የተመረጠ አቅራቢ ካርድ ወይም የዋጋ ሁኔታ ሳጥን። ቦታዎቹን፣ የምሳሌ ዋጋዎቹንና ቅጹን ለማየት ቁልፉን ይጫኑ።",
"A newsletter item, a banner in the slideshow, a featured-supplier card or a price-pulse tile. Press the button to see the placements, the prices and the form.": "የጋዜጣ ጽሑፍ፣ በተንሸራታች ምስሎች ውስጥ ባነር፣ የተመረጠ አቅራቢ ካርድ ወይም የዋጋ ሁኔታ ሳጥን። ቦታዎቹን፣ የምሳሌ ዋጋዎቹንና ቅጹን ለማየት ቁልፉን ይጫኑ።",
"A percentage of each completed sale, published on the website. No fee for registration or for sending requests.": "ከእያንዳንዱ የተጠናቀቀ ሽያጭ የሚወሰድ መቶኛ፣ በድረ-ገጹ ላይ ይፋ የተደረገ። ለመመዝገብ ወይም ጥያቄ ለመላክ ክፍያ የለም።",
"A person": "ግለሰብ",
"A problem found at handover is reported on the platform within {1} hours; Build Smartly mediates within one working day.": "በርክክብ ወቅት የተገኘ ችግር በ{1} ሰዓታት ውስጥ በመድረኩ ላይ ሪፖርት ይደረጋል፤ Build Smartly በአንድ የሥራ ቀን ውስጥ ያሸማግላል።",
"A profile is published only after Build Smartly staff have reviewed it. Sponsored cards are marked.": "መግለጫ የሚታተመው የBuild Smartly ሠራተኞች ከገመገሙት በኋላ ብቻ ነው። በስፖንሰር የቀረቡ ካርዶች ምልክት ይደረግባቸዋል።",
