"A slide with the picture, the company and one headline.": "ምስሉን፣ ድርጅቱንና አንድ ዋና ርዕስ የያዘ ስላይድ።",
"A slide with the picture, the company and one headline. It appears within seconds on the home page, in every member's workspace and on the newsletter page. Brands, suppliers and contractors who pay for a slide are set up here.": "ምስሉን፣ ድርጅቱንና አንድ ርዕስ የያዘ ተንሸራታች ምስል። በሰከንዶች ውስጥ በመነሻ ገጹ፣ በእያንዳንዱ አባል የሥራ ገጽና በዜና መጽሔት ገጹ ላይ ይታያል። ለተንሸራታች ምስል የሚከፍሉ ብራንዶች፣ አቅራቢዎችና ኮንትራክተሮች እዚህ ይዘጋጃሉ።",
"A supplier you signed up by phone or in person. They sign in to the supplier portal with this mobile number and password, receive only the requests in their categories, and can keep their own price list. Documents can be added later from their portal.": "በስልክ ወይም በአካል ያስመዘገቡት አቅራቢ። በዚህ የሞባይል ቁጥርና የይለፍ ቃል ወደ አቅራቢ ፖርታል ይገባል፣ በዘርፎቹ ያሉ ጥያቄዎችን ብቻ ይቀበላል፣ የራሱንም የዋጋ ዝርዝር መያዝ ይችላል። ሰነዶች በኋላ ከፖርታሉ ሊጨመሩ ይችላሉ።",
"A tile in the moving price strip on the home page, or a slide in the banner inside every member's workspace.": "በመነሻ ገጹ ላይ በሚንቀሳቀሰው የዋጋ መስመር ውስጥ ያለ ሳጥን፣ ወይም በእያንዳንዱ አባል የሥራ ገጽ ውስጥ ባለው ባነር ላይ ያለ ስላይድ።",
"A {1}-minute walkthrough with sound (turn your volume up): a buyer sends a request, suppliers quote, the buyer chooses and completes the order, agrees to the contracts, receives the goods and pays; then the staff page and the three languages.": "የ{1} ደቂቃ ማብራሪያ ቪዲዮ ከድምፅ ጋር (ድምፁን ከፍ ያድርጉ)፦ ገዢው ጥያቄ ይልካል፣ አቅራቢዎች ዋጋ ይሰጣሉ፣ ገዢው መርጦ ትዕዛዙን ያጠናቅቃል፣ ውሎቹን ይስማማል፣ ዕቃዎቹን ተቀብሎ ይከፍላል፤ ከዚያም የሠራተኞች ገጽና ሦስቱ ቋንቋዎች።",
"A {1}-minute walkthrough: a buyer sends a request, offers arrive, the order goes through contract, delivery and payment, then the supplier portal and the staff page.": "የ{1} ደቂቃ ማብራሪያ፦ ገዢ ጥያቄ ይልካል፣ ቅናሾች ይደርሳሉ፣ ትዕዛዙ በውል፣ በማድረስና በክፍያ ያልፋል፤ ከዚያ የአቅራቢ መግቢያና የሠራተኞች ገጽ።",
