"Choose at least one category.": "ቢያንስ አንድ ዘርፍ ይምረጡ።",
"Choose on the request whether the supplier delivers, you collect, or Build Smartly arranges transport. You can pin the exact site on the map or use your location, and add transit insurance ({1} % of the goods value). When the truck leaves you get a {2}-digit handover code by SMS; check the goods, then give the code to the driver, who types it on their tracking page. Giving the code is your signature that you received the goods.": "በጥያቄው ላይ አቅራቢው ያድርስ፣ እርስዎ ይውሰዱ ወይም Build Smartly ትራንስፖርት ያዘጋጅ እንደሆነ ይምረጡ። ትክክለኛውን ቦታ በካርታ ላይ መጠቆም ወይም አካባቢዎን መጠቀም፣ እና የትራንዚት ኢንሹራንስ ({1} % የዕቃው ዋጋ) ማከል ይችላሉ። መኪናው ሲነሳ ባለ {2} አሃዝ የርክክብ ኮድ በኤስኤምኤስ ይደርስዎታል፤ ዕቃውን ይፈትሹ፣ ከዚያ ኮዱን ለሾፌሩ ይስጡ፣ እሱም በክትትል ገጹ ላይ ያስገባዋል። ኮዱን መስጠት ዕቃውን እንደተቀበሉ የሚያረጋግጥ ፊርማዎ ነው።",
"Choose on the request whether the supplier delivers, you collect, or Build Smartly arranges transport. You can pin the exact site on the map or use your location, and add transit insurance ({1} % of the goods value). When the truck leaves you get a {2}-digit handover code by SMS; give it to the driver and confirm receipt on the order page.": "በጥያቄው ላይ አቅራቢው ያድርስ፣ እርስዎ ይውሰዱ ወይስ Build Smartly ማጓጓዣ ያዘጋጅ እንደሆነ ይምረጡ። ትክክለኛውን ሳይት በካርታው ላይ ምልክት ማድረግ ወይም አካባቢዎን መጠቀም፣ እንዲሁም የማጓጓዣ ኢንሹራንስ ማከል ይችላሉ (ከዕቃው ዋጋ {1} %፣ የምሳሌ ተመን)። መኪናው ሲነሳ ባለ {2} አሃዝ የርክክብ ኮድ በSMS ይደርስዎታል፤ ለሾፌሩ ይስጡትና በትዕዛዝ ገጹ ላይ መቀበልዎን ያረጋግጡ።",
"Choose on the request whether the supplier delivers, you collect, or Build Smartly arranges transport. You can pin the exact site on the map or use your location, and add transit insurance ({1} % of the goods value, example rate). When the truck leaves you get a {2}-digit handover code by SMS; give it to the driver and confirm receipt on the order page.": "በጥያቄው ላይ አቅራቢው ያድርስ፣ እርስዎ ይውሰዱ ወይስ Build Smartly ማጓጓዣ ያዘጋጅ እንደሆነ ይምረጡ። ትክክለኛውን ሳይት በካርታው ላይ ምልክት ማድረግ ወይም አካባቢዎን መጠቀም፣ እንዲሁም የማጓጓዣ ኢንሹራንስ ማከል ይችላሉ (ከዕቃው ዋጋ {1} %፣ የምሳሌ ተመን)። መኪናው ሲነሳ ባለ {2} አሃዝ የርክክብ ኮድ በSMS ይደርስዎታል፤ ለሾፌሩ ይስጡትና በትዕዛዝ ገጹ ላይ መቀበልዎን ያረጋግጡ።",
