"Every message members send from their Mailbox, the help box or the supplier portal. Reply here; the member sees it in the Mailbox and gets an SMS.": "አባላት ከመልዕክት ሳጥናቸው፣ ከእገዛ ሳጥኑ ወይም ከአቅራቢ ፖርታሉ የሚልኩት እያንዳንዱ መልዕክት። እዚህ ይመልሱ፤ አባሉ በመልዕክት ሳጥኑ ያየዋል እና SMS ይደርሰዋል።",
"Every price carries a confirmation time and expiry. Stale prices are never shown as current.": "እያንዳንዱ ዋጋ የተረጋገጠበት ጊዜ እና የሚያበቃበት ቀን አለው። ጊዜው ያለፈበት ዋጋ እንደ ወቅታዊ ዋጋ ፈጽሞ አይታይም።",
"Every purchase order, contract and receipt, by year. View, print or save as PDF for your records.": "እያንዳንዱ የግዢ ትዕዛዝ፣ ውል እና ደረሰኝ በዓመት። ለመዝገብዎ ይመልከቱ፣ ያትሙ ወይም በPDF ያስቀምጡ።",
"Every purchase order, contract and receipt, by year. View, print or save as PDF.": "እያንዳንዱ የግዢ ትዕዛዝ፣ ውል እና ደረሰኝ በዓመት። ይመልከቱ፣ ያትሙ ወይም በPDF ያስቀምጡ።",
"Every request, offer, order, message, problem, newsletter item, promotion, profile, task and supplier change is deleted for everyone. This cannot be undone.": "እያንዳንዱ ጥያቄ፣ ዋጋ ማቅረቢያ፣ ትዕዛዝ፣ መልዕክት፣ ችግር፣ የዜና መጽሔት ጽሑፍ፣ ማስታወቂያ፣ መገለጫ፣ ተግባርና የአቅራቢ ለውጥ ለሁሉም ይሰረዛል። ይህ መመለስ አይቻልም።",
