"Go to Send a request, tick the materials you need, type the quantity and the date you need them, choose the delivery site and press Send. You sign in with your mobile number and the SMS code at that moment; no form to fill. You can also download the Excel template, let your engineer fill it, and upload it.": "ወደ «ጥያቄ ይላኩ» ይሂዱ፣ የሚፈልጓቸውን ዕቃዎች ምልክት ያድርጉ፣ ብዛቱንና የሚፈልጉበትን ቀን ይጻፉ፣ የሚደርስበትን ሳይት ይምረጡና «ላክ»ን ይጫኑ። በዚያን ጊዜ በሞባይል ቁጥርዎና በSMS ኮድ ይገባሉ፤ የሚሞላ ቅጽ የለም። የExcel ቅጹን አውርደው መሐንዲስዎ እንዲሞላው ማድረግና መጫንም ይችላሉ።",
