"I passed nothing on because you are not signed in. Sign in and ask again, and a person from Build Smartly answers. I can also explain requests, offers, contracts, payment, delivery or registering as a supplier.": "ስላልገቡ ምንም ነገር አላስተላለፍኩም። ይግቡና እንደገና ይጠይቁ፤ ከBuild Smartly አንድ ሰው ይመልስልዎታል። ስለ ጥያቄዎች፣ ዋጋ ማቅረቢያዎች፣ ውሎች፣ ክፍያ፣ ማድረስ ወይም እንደ አቅራቢ መመዝገብ ማብራራትም እችላለሁ።",
