"No items yet. Tick the items you sell above, or paste rows from Excel.": "እስካሁን ምንም ዕቃ የለም። የሚሸጧቸውን ዕቃዎች ከላይ ምልክት ያድርጉ፣ ወይም ረድፎችን ከExcel ይለጥፉ።",
"No lines found. Use the template: one item per row with its quantity.": "ምንም መስመር አልተገኘም። ቅጹን ይጠቀሙ፦ በእያንዳንዱ ረድፍ አንድ ዕቃ ከብዛቱ ጋር።",
"No locations yet. Suppliers who add dispatch points receive more requests.": "እስካሁን ምንም አድራሻ የለም። የመላኪያ ቦታ የሚያክሉ አቅራቢዎች ብዙ ጥያቄዎች ይደርሷቸዋል።",
"No messages yet. Ask anything about a request, an offer, a delivery or your documents.": "እስካሁን መልዕክት የለም። ስለ ጥያቄ፣ ዋጋ ማቅረቢያ፣ ማድረስ ወይም ሰነዶችዎ ማንኛውንም ነገር ይጠይቁ።",
"No messages yet. The other party and Build Smartly staff see what you write here.": "እስካሁን መልዕክት የለም። እዚህ የሚጽፉትን ሌላኛው ወገንና የBuild Smartly ሠራተኞች ያዩታል።",
"No offer matches.": "የሚዛመድ ዋጋ ማቅረቢያ የለም።",
"No offers yet": "እስካሁን ዋጋ ማቅረቢያ የለም",
"No offers yet. You get a notification when the first one arrives.": "እስካሁን ዋጋ አልቀረበም። የመጀመሪያው ሲደርስ ማሳወቂያ ይደርስዎታል።",
"No open offers.": "ክፍት ዋጋ ማቅረቢያ የለም።",
"No open requests in your categories right now. When a customer sends a BOQ with your materials, it appears here and you get a notification.": "በአሁኑ ጊዜ በእርስዎ ምድቦች ክፍት ጥያቄ የለም። ደንበኛ የእርስዎን ዕቃዎች የያዘ BOQ ሲልክ እዚህ ይታያል፤ ማሳወቂያም ይደርስዎታል።",
"No order matches.": "የሚዛመድ ትዕዛዝ የለም።",
"No orders won yet.": "እስካሁን ያሸነፉት ትዕዛዝ የለም።",
"No orders yet. When a customer completes an order with your offers, it appears here.": "እስካሁን ትዕዛዝ የለም። ደንበኛ በእርስዎ ዋጋ ማቅረቢያ ትዕዛዝ ሲያጠናቅቅ እዚህ ይታያል።",
"No paid orders yet.": "እስካሁን የተከፈለ ትዕዛዝ የለም።",
"No phone numbers, addresses or prices in the introduction. Moderators check this.": "በመግቢያው ውስጥ ስልክ ቁጥር፣ አድራሻ ወይም ዋጋ አይጻፉ። ተቆጣጣሪዎች ይህን ያረጋግጣሉ።",
"No phone numbers, addresses, price tags or QR codes in pictures. A moderator checks before publishing.": "በምስሎች ላይ ስልክ ቁጥር፣ አድራሻ፣ የዋጋ መለያ ወይም QR ኮድ አይኑር። ከመታተሙ በፊት ተቆጣጣሪ ያረጋግጣል።",
"No picture yet.": "እስካሁን ምስል የለም።",
"No promotions added yet. The examples below show until you add real ones.": "እስካሁን ማስታወቂያ አልተጨመረም። እውነተኛዎቹን እስኪጨምሩ ድረስ ከታች ያሉት ምሳሌዎች ይታያሉ።",
"No requests waiting.": "የሚጠብቅ ጥያቄ የለም።",
"No requests yet. Send one from the New request tab.": "እስካሁን ጥያቄ የለም። ከ«አዲስ ጥያቄ» ገጽ አንድ ይላኩ።",
"No requests yet. Start with": "እስካሁን ጥያቄ የለም። ለመጀመር፦",
"No staff account with that number and password.": "በዚህ ቁጥርና የይለፍ ቃል የሠራተኛ አካውንት የለም።",
"No supplier account with that number": "በዚህ ቁጥር የአቅራቢ አካውንት የለም",
"No. Registration is free for customers and suppliers. A fee applies only when a deal is completed, as a small percentage of the order. The rate will be published before launch.": "አይ። ምዝገባ ለደንበኞችም ለአቅራቢዎችም ነፃ ነው። ክፍያ የሚጠየቀው ስምምነት ሲጠናቀቅ ብቻ ነው፤ ከትዕዛዙ ዋጋ አነስተኛ መቶኛ። መጠኑ ሥራ ከመጀመሩ በፊት ይፋ ይደረጋል።",
"No. They are indicative prices confirmed by suppliers that morning. A binding price comes only as a written offer on your request, with a validity date.": "አይ። እነዚህ በዚያው ጠዋት በአቅራቢዎች የተረጋገጡ አመላካች ዋጋዎች ናቸው። አስገዳጅ ዋጋ የሚመጣው ለጥያቄዎ በጽሑፍ በሚቀርብና የጸናበት ቀን ባለው ዋጋ ማቅረቢያ ብቻ ነው።",
