"Nothing yet. Purchase orders, contracts and receipts appear here.": "እስካሁን ምንም የለም። የግዢ ትዕዛዞች፣ ውሎችና ደረሰኞች እዚህ ይታያሉ።",
"Notification box": "የማሳወቂያ ሳጥን",
"Notifications": "ማሳወቂያዎች",
"Notifications are SMS first. In Settings you can switch on Telegram as well. Telegram can also be used to send a request, never to sign in.": "ማሳወቂያዎች በመጀመሪያ በSMS ይላካሉ። በማስተካከያዎች ውስጥ Telegramንም ማብራት ይችላሉ። Telegram ጥያቄ ለመላክም ያገለግላል፤ ለመግባት ግን ፈጽሞ አያገለግልም።",
"Notifications, inbox, sent, text messages in one place": "ማሳወቂያዎች፣ የገቢ መልዕክቶች፣ የተላኩ፣ የጽሑፍ መልዕክቶች በአንድ ቦታ",
"Notifications, locations, public profile": "ማሳወቂያዎች፣ አድራሻዎች፣ የሕዝብ መገለጫ",
