"Ochre E{1}A{2}A": "ኦከር E{1}A{2}A",
"Off-white F{1}F{2}F{3}": "ደብዛዛ ነጭ F{1}F{2}F{3}",
"Offer A, B, C layout, PO issue": "የዋጋ ማቅረቢያ A፣ B፣ C አቀማመጥ፣ PO መስጠት",
"Offer from Addis Steel & Rebar Trading on BS-{1}-{2} line {3} · ETB {4}": "ከAddis Steel & Rebar Trading ለBS-{1}-{2} መስመር {3} የቀረበ ዋጋ · ETB {4}",
"Offer from Ethio Build Mart on BS-{1}-{2} line {3} · ETB {4}": "ከEthio Build Mart ለBS-{1}-{2} መስመር {3} የቀረበ ዋጋ · ETB {4}",
"Offer from Kality Cement Distributors PLC on BS-{1}-{2} line {3} · ETB {4}": "ከKality Cement Distributors PLC ለBS-{1}-{2} መስመር {3} የቀረበ ዋጋ · ETB {4}",
"Offer from Yerer Equipment Rental on BS-{1}-{2} line {3} · ETB {4}": "ከYerer Equipment Rental ለBS-{1}-{2} መስመር {3} የቀረበ ዋጋ · ETB {4}",
"Offer sent. The customer sees it as an anonymous offer.": "ዋጋው ተልኳል። ደንበኛው ስም የሌለው ዋጋ ማቅረቢያ ሆኖ ያየዋል።",
"Offer sent: ETB {1} per m², delivery ETB {2} valid {3} days.": "ዋጋ ተልኳል፦ በm² ETB {1}፣ ማጓጓዣ ETB {2}፣ ለ{3} ቀናት የሚጸና።",
"Offer sent: ETB {1} per quintal, delivery ETB {2} valid {3} days.": "ዋጋ ተልኳል፦ በኩንታል ETB {1}፣ ማጓጓዣ ETB {2}፣ ለ{3} ቀናት የሚጸና።",
"Offers": "ዋጋ ማቅረቢያዎች",
"Offers A, B, C with delivered price. Accept per item.": "ዋጋ ማቅረቢያ A፣ B፣ C ከማጓጓዣ ጋር ባለው ዋጋ። በእያንዳንዱ ዕቃ ይቀበሉ።",
"Offers and accept per line": "ዋጋ ማቅረቢያዎችና በየመስመሩ መቀበል",
"Offers and orders": "ዋጋ ማቅረቢያዎችና ትዕዛዞች",
"Offers and orders:": "ዋጋ ማቅረቢያዎችና ትዕዛዞች፦",
"Offers appear under My requests, cheapest delivered price first, with the brand but not the supplier name. Press Accept best on a line, or Accept the best price on all lines. You can also counter a price or reject an offer. You get an SMS when offers arrive.": "ዋጋ ማቅረቢያዎች በ«የእኔ ጥያቄዎች» ስር ይታያሉ፤ እስከ ሳይት የሚደርሰው ርካሹ ዋጋ መጀመሪያ፣ ከብራንዱ ጋር እንጂ ከአቅራቢው ስም ጋር አይደለም። በአንድ መስመር ላይ «ምርጡን ተቀበል»ን ወይም «በሁሉም መስመሮች ምርጡን ዋጋ ተቀበል»ን ይጫኑ። ሌላ ዋጋ ማቅረብ ወይም ዋጋ ማቅረቢያን ውድቅ ማድረግም ይችላሉ። ዋጋ ማቅረቢያዎች ሲደርሱ SMS ይደርስዎታል።",
"Offers arrive by themselves within a few minutes. Or open the": "ዋጋ ማቅረቢያዎች በጥቂት ደቂቃዎች ውስጥ በራሳቸው ይደርሳሉ። ወይም ይህን ይክፈቱ፦",
"Offers arriving": "ዋጋ ማቅረቢያዎች እየደረሱ ነው",
"Offers arriving · {1} offer to compare": "ዋጋ ማቅረቢያዎች እየደረሱ ነው · የሚነጻጸር {1} ዋጋ",
"Offers arriving · {1} offers to compare": "ዋጋ ማቅረቢያዎች እየደረሱ ነው · የሚነጻጸሩ {1} ዋጋዎች",
"Offers per line": "በየመስመሩ ዋጋ ማቅረቢያዎች",
