"On delivery, through the Yagout Pay gateway; the platform fee of {1} % is charged to the supplier.": "ዕቃው ሲደርስ፣ በYagout Pay የክፍያ መግቢያ በኩል፤ የመድረኩ ክፍያ {1} % ከአቅራቢው ይጠየቃል።",
"On servers in Ethiopia, as required by the Personal Data Protection Proclamation. Your location and documents are private and are never shown on a public profile.": "በግል መረጃ ጥበቃ አዋጅ መሠረት በኢትዮጵያ ውስጥ ባሉ ሰርቨሮች ላይ። አድራሻዎና ሰነዶችዎ ሚስጥራዊ ናቸው፤ በሕዝብ መገለጫ ላይ በፍጹም አይታዩም።",
"On servers in Ethiopia. Cross-border transfers only as the law allows.": "በኢትዮጵያ ውስጥ ባሉ ሰርቨሮች ላይ። ከአገር ውጭ ማስተላለፍ የሚቻለው ሕጉ በሚፈቅደው መሠረት ብቻ ነው።",
"On shipping": "ዕቃው ሲጫን",
"On the order page there is Report a problem. Build Smartly staff see it at once, track it until it is resolved, and answer within one working day. For anything else, write to support from your Mailbox or ask me to hand you over.": "በትዕዛዝ ገጹ ላይ «ችግር ያሳውቁ» አለ። የBuild Smartly ሠራተኞች ወዲያውኑ ያዩታል፣ እስኪፈታ ይከታተሉታል፣ በአንድ የሥራ ቀን ውስጥም ይመልሳሉ። ለሌላ ማንኛውም ጉዳይ ከመልዕክት ሳጥንዎ ለድጋፍ ይጻፉ ወይም ወደ ሰው እንዳስተላልፍዎ ይጠይቁኝ።",
"On the way": "በመንገድ ላይ",
"On this device only": "በዚህ መሣሪያ ላይ ብቻ",
"Once the supplier reconfirms and the buyer agrees, neither party may withdraw.": "አቅራቢው ዳግም ካረጋገጠና ገዢው ከተስማማ በኋላ ማንኛውም ወገን ማፈግፈግ አይችልም።",
"One account for buying and supplying. A supplier can also send requests.": "ለመግዛትና ለማቅረብ አንድ አካውንት። አቅራቢም ጥያቄ መላክ ይችላል።",
"One account per person or organisation. Suppliers must hold a valid business licence. Documents are checked by staff before trading. Accounts with expired documents are restricted.": "ለአንድ ሰው ወይም ድርጅት አንድ አካውንት። አቅራቢዎች የጸና የንግድ ፈቃድ ሊኖራቸው ይገባል። ሰነዶች ግብይት ከመጀመሩ በፊት በሠራተኞች ይመረመራሉ። ጊዜው ያለፈበት ሰነድ ያላቸው አካውንቶች ይገደባሉ።",
"One-stop supplier for every stage of the build, from cement to finishing. Showroom and yard at Megenagna.": "ከሲሚንቶ እስከ ማጠናቀቂያ ለእያንዳንዱ የግንባታ ደረጃ ሁሉንም በአንድ ቦታ የሚያቀርብ። የማሳያ ክፍልና መጋዘን በMegenagna።",
"Only buying? Sign in with your number": "የሚገዙ ብቻ ነዎት? በቁጥርዎ ይግቡ",
"Only registered suppliers can see requests and quote. A buyer number cannot sign in here.": "ጥያቄዎችን ማየትና ዋጋ ማቅረብ የሚችሉት የተመዘገቡ አቅራቢዎች ብቻ ናቸው። የገዢ ቁጥር እዚህ መግባት አይችልም።",
"Only suppliers of that material see your lines. Your name stays hidden.": "መስመሮችዎን የሚያዩት የዚያ ዕቃ አቅራቢዎች ብቻ ናቸው። ስምዎ ተደብቆ ይቆያል።",
"Only the staff whose job needs it, and only with a log entry. Other members see your identity only in a purchase order. Nothing is sold or shared with advertisers.": "ሥራቸው የሚጠይቅባቸው ሠራተኞች ብቻ፣ ያውም በመዝገብ ተመዝግቦ። ሌሎች አባላት ማንነትዎን የሚያዩት በግዢ ትዕዛዝ ውስጥ ብቻ ነው። ምንም ነገር ለማስታወቂያ አስነጋሪዎች አይሸጥም ወይም አይሰጥም።",
"Only verified suppliers of the materials on your list. They see a customer number and the sub-city of delivery, never your name or exact address. Your identity appears only in the purchase order.": "በዝርዝርዎ ላይ ያሉትን ዕቃዎች የሚያቀርቡ የተረጋገጡ አቅራቢዎች ብቻ። የደንበኛ ቁጥርና የማድረሻውን ክፍለ ከተማ ያያሉ፤ ስምዎን ወይም ትክክለኛ አድራሻዎን በፍጹም አያዩም። ማንነትዎ የሚታየው በግዢ ትዕዛዙ ውስጥ ብቻ ነው።",
"Only your mobile number. Build your list, press Send, type the SMS code. That is the account. Your list is saved on your phone while you do it, so you can leave and come back.": "የሞባይል ቁጥርዎ ብቻ። ዝርዝርዎን ያዘጋጁ፣ «ላክ»ን ይጫኑ፣ የSMS ኮዱን ይጻፉ። አካውንቱ ይኸው ነው። ዝርዝርዎ በሚያዘጋጁበት ጊዜ በስልክዎ ላይ ይቀመጣል፤ ስለዚህ ወጥተው መመለስ ይችላሉ።",
