"Owner only. Each staff member signs in with their own email and password. Tick the pages each person may open.": "ለባለቤቱ ብቻ። እያንዳንዱ ሠራተኛ በራሱ ኢሜይልና የይለፍ ቃል ይገባል። እያንዳንዱ ሰው ሊከፍታቸው የሚችላቸውን ገጾች ምልክት ያድርጉ።",
