"Tip: use two browser windows, one as the buyer and one as a supplier.": "ጠቃሚ ምክር፦ ሁለት የብራውዘር መስኮቶችን ይጠቀሙ፤ አንዱን እንደ ገዢ፣ ሌላውን እንደ አቅራቢ።",
