"Transport to Bole: about {1} km from Akaki Kaliti, {2} truck trip ({3} t) · typical cost ETB {4}. Pre-filled below; change it to your own figure, or put {5} and quote a delivered unit price.": "ትራንስፖርት ወደ Bole፦ ከAkaki Kaliti {1} km ገደማ፣ {2} የጭነት መኪና ጉዞ ({3} t) · በምሳሌ ታሪፉ የተለመደው ወጪ ETB {4}። ከታች አስቀድሞ ተሞልቷል፤ በራስዎ አሃዝ ይቀይሩት፣ ወይም {5} አስገብተው ማድረሻን ያካተተ የአንዱን ዋጋ ያቅርቡ።",
"Transport to Bole: about {1} km from Akaki Kaliti, {2} truck trips ({3} t) · typical cost ETB {4} at the example tariff. Pre-filled below; change it to your own figure, or put {5} and quote a delivered unit price.": "ትራንስፖርት ወደ Bole፦ ከAkaki Kaliti {1} km ገደማ፣ {2} የጭነት መኪና ጉዞዎች ({3} t) · በምሳሌ ታሪፉ የተለመደው ወጪ ETB {4}። ከታች አስቀድሞ ተሞልቷል፤ በራስዎ አሃዝ ይቀይሩት፣ ወይም {5} አስገብተው ማድረሻን ያካተተ የአንዱን ዋጋ ያቅርቡ።",
"Transport to Bole: about {1} km from Akaki Kaliti, {2} truck trips ({3} t) · typical cost ETB {4}. Pre-filled below; change it to your own figure, or put {5} and quote a delivered unit price.": "ትራንስፖርት ወደ Bole፦ ከAkaki Kaliti {1} km ገደማ፣ {2} የጭነት መኪና ጉዞዎች ({3} t) · በምሳሌ ታሪፉ የተለመደው ወጪ ETB {4}። ከታች አስቀድሞ ተሞልቷል፤ በራስዎ አሃዝ ይቀይሩት፣ ወይም {5} አስገብተው ማድረሻን ያካተተ የአንዱን ዋጋ ያቅርቡ።",
"Truck": "መኪና",
"Truck capacity (tonnes)": "የመኪና የመጫን አቅም (ቶን)",
"Truck plate (optional)": "የመኪና ሰሌዳ ቁጥር (አማራጭ)",
"Truck: cost per km (ETB)": "መኪና፦ በኪሎ ሜትር ወጪ (ETB)",
"Truck: fixed cost per trip (ETB)": "መኪና፦ ለአንድ ጉዞ ቋሚ ወጪ (ETB)",
"Try the BOQ form": "የBOQ ቅጹን ይሞክሩ",
"Try with an example list": "በምሳሌ ዝርዝር ይሞክሩ",
"Two minutes to register. Documents are asked for only before your first order.": "ለመመዝገብ ሁለት ደቂቃ። ሰነዶች የሚጠየቁት ከመጀመሪያ ትዕዛዝዎ በፊት ብቻ ነው።",
