"Type the code here to confirm the delivery. Something wrong? Report it within {1} hours.": "መድረሱን ለማረጋገጥ ኮዱን እዚህ ያስገቡ። ችግር አለ? በ{1} ሰዓት ውስጥ ያሳውቁ።",
"Type the driver's mobile, for example {1}.": "የሾፌሩን ሞባይል ያስገቡ፣ ለምሳሌ {1}።",
"Type the driver's name.": "የሾፌሩን ስም ያስገቡ።",
"Type the items or upload your BOQ. Set a deadline.": "ዕቃዎቹን ይጻፉ ወይም BOQዎን ይጫኑ። የመጨረሻ ቀን ይወስኑ።",
"Type the price, VAT, minimum order, stock and how long the price holds. A price older than its validity is marked stale and never shown as current. Your quotes are pre-filled from here.": "ዋጋውን፣ VAT-ን፣ ዝቅተኛ ትዕዛዝን፣ ክምችትንና ዋጋው ለምን ያህል ጊዜ እንደሚጸና ይጻፉ። የሚጸናበት ጊዜ ያለፈ ዋጋ «ጊዜው ያለፈ» ተብሎ ይለያል፤ እንደ ወቅታዊ ዋጋ ፈጽሞ አይታይም። የዋጋ ማቅረቢያዎችዎ ከዚህ አስቀድመው ይሞላሉ።",
"Type the quantity for each item and when you need it. Earliest date:": "ለእያንዳንዱ ዕቃ መጠኑንና የሚፈልጉበትን ቀን ይጻፉ። መጀመሪያ ሊሆን የሚችለው ቀን፦",
"Type your message…": "መልዕክትዎን ይጻፉ…",
"Type your {1}-digit handover code to confirm.": "ለማረጋገጥ ባለ {1} አሃዝ የርክክብ ኮድዎን ያስገቡ።",
"Typed by the customer, not in the catalogue": "በደንበኛው የተጻፈ፣ በካታሎጉ ውስጥ የሌለ",
"Under each offer there is a box \"Your price per unit\" and a Counter button. The supplier accepts or declines; if accepted the order is issued at your price. The original offer stays valid meanwhile.": "በእያንዳንዱ ዋጋ ማቅረቢያ ስር «የእርስዎ ዋጋ በአንድ መለኪያ» የሚል ሳጥንና «ሌላ ዋጋ አቅርብ» ቁልፍ አለ። አቅራቢው ይቀበላል ወይም አይቀበልም፤ ከተቀበለ ትዕዛዙ በእርስዎ ዋጋ ይሰጣል። እስከዚያው የመጀመሪያው ዋጋ ማቅረቢያ ጸንቶ ይቆያል።",
"Unit": "መለኪያ",
"Unit price": "ነጠላ ዋጋ",
"Unit price (ETB)": "ነጠላ ዋጋ (ETB)",
"Update many at once": "ብዙዎችን በአንድ ጊዜ ያዘምኑ",
"Update prices from your phone, confirm unchanged prices in one action, or upload your whole list from Excel. You only receive requests for materials you sell, and you pay nothing until a deal completes.": "ዋጋዎችን ከስልክዎ ያዘምኑ፣ ያልተቀየሩ ዋጋዎችን በአንድ ጊዜ ያረጋግጡ፣ ወይም ሙሉ ዝርዝርዎን ከExcel ይጫኑ። የሚደርስዎ ለሚሸጧቸው ዕቃዎች የሚቀርብ ጥያቄ ብቻ ነው፤ ሽያጭ እስኪጠናቀቅ ምንም አይከፍሉም።",
"Upload photo": "ፎቶ ይጫኑ",
"Upload the business licence and TIN certificate under Settings → Documents. Staff review within {1} working days; until then quoting is locked.": "የንግድ ፈቃዱንና የTIN ሰርተፊኬቱን በማስተካከያዎች → ሰነዶች ስር ይጫኑ። ሠራተኞች በ{1} የሥራ ቀናት ውስጥ ይገመግማሉ፤ እስከዚያው ዋጋ ማቅረብ አይቻልም።",
