"We are building one place where a contractor sends a list once, verified suppliers quote in writing, and the purchase order and contract are issued with a full record. Addis Ababa first, then the regional cities.": "ኮንትራክተሩ ዝርዝሩን አንድ ጊዜ የሚልክበት፣ የተረጋገጡ አቅራቢዎች በጽሑፍ ዋጋ የሚሰጡበት፣ የግዢ ትዕዛዝና ውሉም ከሙሉ መዝገብ ጋር የሚወጣበት አንድ ቦታ እየገነባን ነው። በመጀመሪያ አዲስ አበባ፣ ከዚያም የክልል ከተሞች።",
"We send a {1}-digit code by SMS, and we text you when offers are ready. That is your whole account. Suppliers never see your name, only a customer number.": "የ{1} አሃዝ ኮድ በSMS እንልክልዎታለን፤ ዋጋዎች ሲዘጋጁም በመልዕክት እናሳውቅዎታለን። መለያዎ ይህ ብቻ ነው። አቅራቢዎች ስምዎን አያዩም፣ የደንበኛ ቁጥር ብቻ ነው የሚያዩት።",
