"What buyers received this month. Also in every member's Mailbox under Newsletter.": "ገዢዎች በዚህ ወር የደረሳቸው። በእያንዳንዱ አባል የመልዕክት ሳጥን ውስጥ በዜና መጽሔት ስርም ይገኛል።",
