"When the buyer has checked the goods, ask for their {1}-digit handover code and type it here. A correct code confirms the delivery.": "ገዢው ዕቃውን ከፈተሸ በኋላ ባለ {1} አሃዝ የርክክብ ኮዱን ጠይቀው እዚህ ያስገቡ። ትክክለኛ ኮድ መድረሱን ያረጋግጣል።",
"When the supplier dispatches your order, the driver gets a one-time link and shares the truck's location from their phone. Open the order page: the map shows the truck, the distance left and roughly when it arrives. The link ends at handover or after {1} hours, and no route history is kept.": "አቅራቢው ትዕዛዝዎን ሲልክ ሾፌሩ የአንድ ጊዜ ሊንክ ያገኛል፣ የመኪናውንም አካባቢ ከስልኩ ያጋራል። የትዕዛዝ ገጹን ይክፈቱ፦ ካርታው መኪናውን፣ የቀረውን ርቀት እና በግምት መቼ እንደሚደርስ ያሳያል። ሊንኩ በርክክብ ወይም ከ{1} ሰዓት በኋላ ያበቃል፣ የጉዞ ታሪክም አይቀመጥም።",
"When you accept an offer, Build Smartly issues the purchase order and reveals the supplier. The supplier reconfirms price and stock, then you read the contract on the order page and press Agree. From then on both sides are bound. The PO, the contract and later the receipt can be printed or saved as PDF from the order page.": "አንድ ዋጋ ማቅረቢያ ሲቀበሉ Build Smartly የግዢ ትዕዛዙን ያወጣል፣ አቅራቢውንም ይገልጻል። አቅራቢው ዋጋና ክምችትን ዳግም ያረጋግጣል፤ ከዚያ እርስዎ በትዕዛዝ ገጹ ላይ ውሉን አንብበው «እስማማለሁ»ን ይጫናሉ። ከዚያ ጀምሮ ሁለቱም ወገኖች ይገደዳሉ። PO፣ ውሉና በኋላም ደረሰኙ ከትዕዛዝ ገጹ ሊታተሙ ወይም እንደ PDF ሊቀመጡ ይችላሉ።",
