"Write to Build Smartly support about a request, an offer or a delivery. Amharic, Afaan Oromoo or English. Staff answer here and by SMS; the thread is kept with your account.": "ስለ ጥያቄ፣ ዋጋ ወይም ርክክብ ለBuild Smartly ድጋፍ ይጻፉ። በአማርኛ፣ በአፋን ኦሮሞ ወይም በእንግሊዝኛ። ሠራተኞች እዚህና በSMS ይመልሳሉ፤ ውይይቱ ከመለያዎ ጋር ይቀመጣል።",
"Write to Build Smartly support about a request, an order or your documents. Staff answer here and by SMS.": "ስለ ጥያቄ፣ ትዕዛዝ ወይም ሰነዶችዎ ለBuild Smartly ድጋፍ ይጻፉ። ሠራተኞች እዚህና በSMS ይመልሳሉ።",
"Written from the records above.": "ከላይ ካሉት መዝገቦች የተጻፈ።",
"Written from the records above. Copy it into a proposal to a brand, a supplier or a partner.": "ከላይ ካሉት መዝገቦች የተጻፈ። ለብራንድ፣ ለአቅራቢ ወይም ለአጋር በሚያቀርቡት ሐሳብ ውስጥ ይቅዱት።",
"Written under the Personal Data Protection Proclamation No. {1}/{2}.": "በግል መረጃ ጥበቃ አዋጅ ቁጥር {1}/{2} መሠረት የተዘጋጀ።",
"Wrong email or password.": "ኢሜይል ወይም የይለፍ ቃል ተሳስቷል።",
"Wrong password. On the test site it is \"smartly\".": "የይለፍ ቃሉ ትክክል አይደለም። በሙከራ ጣቢያው ላይ \"smartly\" ነው።",
"Wrong quantity, damage, delay…": "የተሳሳተ መጠን፣ ጉዳት፣ መዘግየት…",
"Yagout Pay · secure payment": "Yagout Pay · ደህንነቱ የተጠበቀ ክፍያ",
"Yes, clear it": "አዎ፣ ሰርዘው",
"Yes, reject it": "አዎ፣ ውድቅ አድርግ",
"Yes, this is planned for launch. The Build Smartly bot will let you send your list as a message, a photo or an Excel file, and will send you notifications when offers arrive. The website and the bot share the same account and the same records.": "አዎ፣ ይህ ለሥራ መጀመሪያ ታቅዷል። የBuild Smartly ቦት ዝርዝርዎን እንደ መልዕክት፣ ፎቶ ወይም Excel ፋይል እንዲልኩ ያስችልዎታል፤ ዋጋዎች ሲደርሱም ያሳውቅዎታል። ድረ-ገጹና ቦቱ አንድ መለያና አንድ መዝገብ ይጋራሉ።",
"Yes. You accept, reject or renegotiate each line separately, and you can split a line between two suppliers if both allow partial supply.": "አዎ። እያንዳንዱን ዝርዝር ለየብቻ ይቀበላሉ፣ ውድቅ ያደርጋሉ ወይም እንደገና ይደራደራሉ፤ ሁለቱም አቅራቢዎች ከፊል አቅርቦት ከፈቀዱ አንድን ዝርዝር በሁለት አቅራቢዎች መካከል መከፋፈል ይችላሉ።",
"You": "እርስዎ",
"You are": "እርስዎ",
"You can also send requests to buy materials with this same account.": "በዚሁ መለያ ዕቃ ለመግዛት ጥያቄም መላክ ይችላሉ።",
"You can see, correct and ask for deletion of your data, subject to legal record-keeping. Write to the contact on the Contact page.": "በሕጋዊ የመዝገብ አያያዝ ግዴታዎች መሠረት መረጃዎን ማየት፣ ማስተካከልና እንዲሰረዝ መጠየቅ ይችላሉ። በ«አግኙን» ገጽ ላይ ላለው አድራሻ ይጻፉ።",
"You pay after the goods are delivered and you confirmed receipt with the handover code. On the order page press Pay, choose Telebirr, CBE Birr, bank transfer or card, and authorise. Yagout Pay confirms, the supplier is paid, and your receipt is under Documents.": "የሚከፍሉት ዕቃው ከደረሰና በርክክብ ኮዱ መቀበልዎን ካረጋገጡ በኋላ ነው። በትዕዛዝ ገጹ ላይ «ክፈል»ን ይጫኑ፣ Telebirr፣ CBE Birr፣ የባንክ ዝውውር ወይም ካርድ ይምረጡና ይፍቀዱ። Yagout Pay ያረጋግጣል፣ ለአቅራቢው ይከፈላል፣ ደረሰኝዎም በሰነዶች ስር ይገኛል። በሙከራ ድረ-ገጹ ላይ ምንም ገንዘብ አይንቀሳቀስም።",
"You pay after the goods are delivered and you confirmed receipt with the handover code. On the order page press Pay, choose Telebirr, CBE Birr, bank transfer or card, and authorise. Yagout Pay confirms, the supplier is paid, and your receipt is under Documents. On the test site no money moves.": "የሚከፍሉት ዕቃው ከደረሰና በርክክብ ኮዱ መቀበልዎን ካረጋገጡ በኋላ ነው። በትዕዛዝ ገጹ ላይ «ክፈል»ን ይጫኑ፣ Telebirr፣ CBE Birr፣ የባንክ ዝውውር ወይም ካርድ ይምረጡና ይፍቀዱ። Yagout Pay ያረጋግጣል፣ ለአቅራቢው ይከፈላል፣ ደረሰኝዎም በሰነዶች ስር ይገኛል። በሙከራ ድረ-ገጹ ላይ ምንም ገንዘብ አይንቀሳቀስም።",
"You proposed ETB {1} · waiting for the supplier's answer": "ETB {1} አቅርበዋል · የአቅራቢውን መልስ በመጠበቅ ላይ",
"You · {1}/{2}/{3} {4}:{5}:{6} PM": "እርስዎ · {1}/{2}/{3} {4}:{5}:{6} ከሰዓት",
"Your account": "መለያዎ",
"Your account is on hold for review. Quoting is locked.": "መለያዎ ለግምገማ ቆሟል። ዋጋ ማቅረብ ተቆልፏል።",
