"Your company or brand name": "የድርጅትዎ ወይም የብራንድዎ ስም",
"Your data stays in Ethiopia": "መረጃዎ በኢትዮጵያ ውስጥ ይቀመጣል",
"Your data stays private and stays in Ethiopia.": "መረጃዎ ሚስጥራዊ ሆኖ በኢትዮጵያ ውስጥ ይቀመጣል።",
"Your dispatch points and prices are never shown to competitors": "የመላኪያ ቦታዎችዎና ዋጋዎችዎ ለተወዳዳሪዎች በፍጹም አይታዩም",
"Your documents": "ሰነዶችዎ",
"Your documents were approved. You can quote.": "ሰነዶችዎ ጸድቀዋል። ዋጋ ማቅረብ ይችላሉ።",
"Your driver entered the buyer's handover code for PO-BS-{1}-{2}-{3}.": "ሾፌርዎ ለPO-BS-{1}-{2}-{3} የገዢውን የርክክብ ኮድ አስገብቷል።",
"Your full name": "ሙሉ ስምዎ",
"Your headline, text and picture in the monthly issue, and your banner in the slideshow on the home page and in every member's workspace.": "ርዕስዎ፣ ጽሑፍዎና ሥዕልዎ በወርሃዊው እትም ላይ፣ ባነርዎ ደግሞ በመነሻ ገጹና በእያንዳንዱ አባል የሥራ ቦታ ስላይድ ትዕይንት ውስጥ።",
"Your licence and TIN are with Build Smartly staff. They review within {1} working days; you get an SMS and quoting opens.": "የንግድ ፈቃድዎና TINዎ በBuild Smartly ሠራተኞች ዘንድ ናቸው። በ{1} የሥራ ቀናት ውስጥ ይገመግማሉ፤ SMS ይደርስዎታል፣ ዋጋ ማቅረብም ይከፈታል።",
"Your licence and TIN were checked. You receive requests in your categories and can quote.": "ፈቃድዎና TINዎ ተረጋግጠዋል። በምድቦችዎ ውስጥ ጥያቄዎች ይደርስዎታል፤ ዋጋም መስጠት ይችላሉ።",
"Your list": "ዝርዝርዎ",
"Your location is no longer shared. Ask the supplier for a new link if the delivery is not finished.": "አካባቢዎ ከእንግዲህ አይጋራም። ማድረሻው ካላለቀ አዲስ ሊንክ አቅራቢውን ይጠይቁ።",
"Your logins": "የመግቢያ መለያዎችዎ",
"Your mobile number": "የሞባይል ቁጥርዎ",
"Your mobile number and an SMS code.": "የሞባይል ቁጥርዎና የSMS ኮድ።",
"Your mobile number and an SMS code. New number? The account is created for you.": "የሞባይል ቁጥርዎና የSMS ኮድ። አዲስ ቁጥር ነው? መለያው ይከፈትልዎታል።",
"Your mobile number is your account": "የሞባይል ቁጥርዎ መለያዎ ነው",
"Your mobile number is your account.": "የሞባይል ቁጥርዎ መለያዎ ነው።",
"Your name": "ስምዎ",
