"Your name, your mobile number and an SMS code. Company details and TIN are asked for before your first purchase order.": "ስምዎ፣ የሞባይል ቁጥርዎና የSMS ኮድ። የድርጅት ዝርዝሮችና TIN ከመጀመሪያው የግዢ ትዕዛዝዎ በፊት ይጠየቃሉ።",
"Your orders": "ትዕዛዞችዎ",
