"Your personal taxpayer number, {1} digits. If you have none, staff ask for your Fayda ID.": "የግል የግብር ከፋይ መለያ ቁጥርዎ፣ {1} አሃዝ። ከሌለዎት ሠራተኞች የFayda መታወቂያዎን ይጠይቃሉ።",
"Your price list (optional) ·": "የዋጋ ዝርዝርዎ (አማራጭ) ·",
