"after a staff check. No addresses, phone numbers or prices in the text.": "ከሠራተኞች ማረጋገጫ በኋላ። በጽሑፉ ውስጥ አድራሻ፣ ስልክ ቁጥር ወይም ዋጋ አያስገቡ።",
"after a staff check. No addresses, phone numbers or prices.": "ከሠራተኞች ማረጋገጫ በኋላ። አድራሻ፣ ስልክ ቁጥር ወይም ዋጋ አያስገቡ።",
